actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate KY state additions
            double additions = 0.0;

            // KY requires addback of:
            // - Federal interest income (U.S. government obligations taxable to KY)
            // - IRC 199A deduction (KY decouples from federal QBI deduction)
            // - State income tax refunds previously deducted
            // - Bonus depreciation amounts (KY may require conformity adjustments)

            // Example additions (would be calculated from entity fields):
            // additions += revenue.federal_bond_interest;
            // additions += result.section_199a_deduction;
            // additions += result.state_tax_refunds;

            apportionment.state_additions = additions;

            // Calculate KY state subtractions
            double subtractions = 0.0;

            // KY allows subtraction of:
            // - KY municipal bond interest (exempt for KY purposes)
            // - Dividends from Kentucky corporations (100% deduction for qualifying dividends)
            // - KY net operating loss deduction (if applicable)

            // Example subtractions (would be calculated from entity fields):
            // subtractions += revenue.ky_municipal_interest;
            // subtractions += result.ky_dividend_deduction;
            // subtractions += result.ky_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // KY uses 4.5% flat rate (effective 2025)
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract KY state credits
            // KY offers various credits: industrial development, film industry,
            // coal incentive, recycling, research and development, etc.
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
